    @Test func theListIsBuildxsRecordsNewestFirst() throws {
        let l = BuildRecord.parseList(Data(Self.list.utf8))
        #expect(l.count == 2)
        let failed = try #require(l.first)
        #expect(failed.name == "ctx2" && failed.state == "failed" && failed.totalSteps == 6 && !failed.ref.contains("/"))
        #expect((failed.duration ?? 0) > 0.5 && (failed.duration ?? 0) < 1)
        #expect(l[1].state == "completed" && l[1].name == "ctx")
    }

    @Test func aBuildsStepsAreInTheOrderTheyRanWithTheirTagsAndLogs() {
        let s = BuildSteps.parse(Data(Self.completed.utf8))
        #expect(s.tags == ["docker.io/library/fevtest-history:1"])
        #expect(s.steps.map(\.name).filter { !$0.hasPrefix("[internal]") } == ["[1/2] COPY a.txt /a.txt", "[2/2] COPY a.txt /b.txt", "exporting to image"])
        #expect(s.steps.filter(\.isInternal).count == 3)
        #expect(s.steps.allSatisfy { $0.state == "completed" && $0.duration != nil })
        let f = BuildSteps.parse(Data(Self.failed.utf8))
        let run = f.steps.first { $0.name.hasPrefix("[2/3] RUN echo") }
        #expect(run?.log == "hello from the build\nsecond line\n")
        let bad = f.steps.first { $0.name == "[3/3] RUN false" }
        #expect(bad?.state == "failed" && (bad?.error.contains("exit code: 1") ?? false))
        #expect(f.tags.isEmpty)
    }

    @Test func goTimesWithNanosecondsAndOffsetsAreRead() {
        let a = BuildTime.parse("2026-10-25T20:44:52.523201796Z"), b = BuildTime.parse("2026-10-25T16:44:52.523201796-04:00")
        #expect(a != nil && a == b)
        #expect(BuildTime.parse("2026-10-25T20:44:52Z") != nil && BuildTime.parse("") == nil)
    }

    @Test func finishedBuildsStepsAreKeptToABudgetTheLeastUsedGoingFirst() {
        func steps(_ log: String) -> BuildSteps {
            BuildSteps(steps: [BuildStep(digest: "d", name: "", started: nil, completed: nil, cached: false, error: "", log: log)], tags: [])
        }
        var c = BuildStepsCache(budget: 10)
        c.put("a", steps("aaaa"))
        c.put("b", steps("bbbb"))
        #expect(c.get("a") != nil)
        c.put("c", steps("cccc"))
        #expect(c.get("b") == nil && c.get("a") != nil && c.get("c") != nil)
        #expect(c.bytes == 8)
        c.put("big", steps(String(repeating: "x", count: 11)))
        #expect(c.get("big") == nil && c.count == 2)
        c.put("a", steps("aa"))
        #expect(c.bytes == 6)
        c.removeAll()
        #expect(c.count == 0 && c.bytes == 0)
    }
}
